const seenTitles = new Map<string, number>();

export const ML_PANEL_PICKS: readonly PanelPick[] = rows.map(
  ([title, pct, extras, price, sold, rating, group, sponsored]) => {
    const n = (seenTitles.get(title) ?? 0) + 1;
    seenTitles.set(title, n);
    return {
      id: n === 1 ? title : `${title} (repetido ${n})`,
      title,
      rate: pct / 100,
      extras: extras === 1,
      price,
      sold,
      rating,
      group,
      ...(sponsored ? { sponsored: true } : {}),
      ...(SEARCHED_TITLES.has(title) ? { searched: true } : {}),
      ...(ML_PANEL_URLS[title] ? { productUrl: ML_PANEL_URLS[title] } : {}),
      capturedAt: D,
    };
  },
);
